<?= view('layout/header', ['title' => 'Staff']) ?><h1>Staff</h1><p><a class="button" href="<?= site_url('staff/new') ?>">Add staff</a></p><div class="panel table-wrap"><table><thead><tr><th>Avatar</th><th>Username</th><th>Full name</th><th>Actions</th></tr></thead><tbody><?php foreach ($items as $item): ?><tr><td><?php if ($url = \App\Libraries\ImageUpload::url($item['avatar'], 'avatars')): ?><img class="thumb" src="<?= esc($url, 'attr') ?>" alt="<?= esc($item['full_name'], 'attr') ?>"><?php else: ?>—<?php endif ?></td><td><?= esc($item['username']) ?></td><td><?= esc($item['full_name']) ?></td><td><div class="actions"><a href="<?= site_url('staff/' . $item['id'] . '/edit') ?>">Edit</a><?php if ((int)session('user_id') !== (int)$item['id']): ?><form method="post" action="<?= site_url('staff/' . $item['id'] . '/archive') ?>" onsubmit="return confirm('Archive this staff account?')"><?= csrf_field() ?><button class="danger">Archive</button></form><?php endif ?></div></td></tr><?php endforeach ?><?php if (! $items): ?><tr><td colspan="4">No staff yet.</td></tr><?php endif ?></tbody></table></div><?= view('layout/footer') ?>
